#include <iostream>
#include <vector>
#include <string>
#include <deque>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long budget;
    cin >> n >> budget;
    vector<long long> charge(n);
    for (int i = 0; i < n; i++) cin >> charge[i];
    vector<long long> running(n);
    for (int i = 0; i < n; i++) cin >> running[i];

    deque<int> dq;
    int left = 0, best = 0;
    long long total = 0;
    for (int right = 0; right < n; right++) {
        while (!dq.empty() && charge[dq.back()] <= charge[right]) dq.pop_back();
        dq.push_back(right);
        total += running[right];
        while (!dq.empty() && charge[dq.front()] + (long long) (right - left + 1) * total > budget) {
            if (dq.front() == left) dq.pop_front();
            total -= running[left];
            left++;
        }
        best = max(best, right - left + 1);
    }
    cout << best << "\n";

    return 0;
}

