import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long budget = Long.parseLong(next());
        long[] charge = new long[(int) n];
        for (int i = 0; i < charge.length; i++) charge[i] = Long.parseLong(next());
        long[] running = new long[(int) n];
        for (int i = 0; i < running.length; i++) running[i] = Long.parseLong(next());

        Deque<Integer> dq = new ArrayDeque<>();
        int left = 0, best = 0;
        long total = 0;
        for (int right = 0; right < n; right++) {
            while (!dq.isEmpty() && charge[dq.peekLast()] <= charge[right]) dq.pollLast();
            dq.addLast(right);
            total += running[right];
            while (!dq.isEmpty() && charge[dq.peekFirst()] + (long) (right - left + 1) * total > budget) {
                if (dq.peekFirst() == left) dq.pollFirst();
                total -= running[left];
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        System.out.println(best);
    }
}
